-- V11: encounters and documents tables + synthetic data
CREATE TABLE IF NOT EXISTS encounters (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id     UUID NOT NULL,
    admission_id   UUID,
    encounter_type TEXT        NOT NULL,
    encounter_ts   TIMESTAMPTZ NOT NULL,
    provider_name  TEXT        NOT NULL,
    notes          TEXT,
    CONSTRAINT fk_enc_patient   FOREIGN KEY (patient_id)   REFERENCES patients(id)   ON DELETE CASCADE,
    CONSTRAINT fk_enc_admission FOREIGN KEY (admission_id) REFERENCES admissions(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_enc_patient_id ON encounters(patient_id);
CREATE INDEX IF NOT EXISTS idx_enc_encounter_ts ON encounters(encounter_ts);
CREATE TABLE IF NOT EXISTS documents (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id   UUID NOT NULL,
    encounter_id UUID,
    doc_type     TEXT        NOT NULL,
    title        TEXT        NOT NULL,
    summary      TEXT,
    created_at   TIMESTAMPTZ NOT NULL,
    CONSTRAINT fk_doc_patient   FOREIGN KEY (patient_id)   REFERENCES patients(id)   ON DELETE CASCADE,
    CONSTRAINT fk_doc_encounter FOREIGN KEY (encounter_id) REFERENCES encounters(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_doc_patient_id ON documents(patient_id);

